import { _decorator, Component, Node } from 'cc';
import { Entity } from './Engine/Entity';
import { Bus } from './Engine/Bus';
import { World } from './Engine/World';
import { ViewRegistry } from './Engine/ViewRegistry';
import { FixedTick } from './Engine/Tick';
import { System } from './Engine/System';
import { TestView } from './TestView';

const { ccclass } = _decorator;

class TestEntity extends Entity {
    readonly kind = 'test';
    public vx = 100;
}

class MovementSystem implements System {
    onTick(world: World, dt: number): void {
        for (const e of world.query<TestEntity>('test')) {
            e.x += e.vx * dt;
            if (e.x > 300) e.x = -300;
        }
    }
}

@ccclass('TestRunner')
export class TestRunner extends Component {

    private _tick: FixedTick = null!;
    private _testMode = 0;   // 0=正常，1=暂停，2=恢复

    start() {
        // 1. 组装 World
        const bus = new Bus();
        const views = new ViewRegistry(this.node);
        views.registerFactory('test', (e) => {
            const node = new Node(`view_${e.id}`);
            return node.addComponent(TestView);
        });

        const world = new World(bus, views);
        world.addSystem(new MovementSystem());

        // 2. 创建 3 个 Entity
        for (let i = 0; i < 3; i++) {
            const e = new TestEntity();
            e.x = -300 + i * 100;
            e.y = i * 80 - 80;
            world.add(e);
        }

        // 3. 挂 FixedTick 并启动
        this._tick = this.node.addComponent(FixedTick);
        this._tick.setup(world, views);
        this._tick.begin();

        // 4. 定时测试暂停/恢复（每 2 秒切换一次）
        this.schedule(() => {
            this._testMode = (this._testMode + 1) % 3;
            if (this._testMode === 1) {
                console.log('[TestRunner] 暂停');
                this._tick.stop();
            } else if (this._testMode === 2) {
                console.log('[TestRunner] 恢复');
                this._tick.begin();
            } else {
                console.log('[TestRunner] 正常运行中');
            }
        }, 2.0);
    }
}